insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', 'N4', 'V（普通形）／Aい／Aな／Nの＋はずです', 'Chắc chắn là ~ (suy luận có căn cứ)', 'はず dùng khi người nói có căn cứ hợp lý để tin rằng điều gì chắc chắn đúng', 'V(thể thường)／Aい／Aな(な)／N(の) + はずです', 'Diễn tả sự suy luận chắc chắn dựa trên căn cứ, lý lẽ hợp lý', NULL, NULL, NULL, '{}', NULL, 45, 'V（普通形）／Aい／Aな／Nの＋はずです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('754f3c2e-1837-4931-a447-9f553b84ea88', 'N4', 'V（普通形）／Aい／Aな（だ）／N（だ）＋そうです（伝聞）', 'Nghe nói ~ (truyền đạt lại thông tin nghe/đọc được)', 'そうです truyền văn gắn sau thể thường nguyên vẹn (khác そうです suy đoán bằng mắt ở round 7, gắn sau gốc Vます/Aい/Aな)', 'V(thể thường)／Aい／Aな(だ)／N(だ) + そうです', 'Truyền đạt lại thông tin đã nghe/đọc được từ người khác hoặc nguồn tin', NULL, NULL, NULL, '{}', NULL, 45, 'V（普通形）／Aい／Aな（だ）／N（だ）＋そうです（伝聞）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e3673d1b-72e3-4112-a5de-f601fbb23ecc', 'N4', 'V（普通形）／Aな（だ）／N（だ）＋ようです', 'Hình như, dường như ~ (phán đoán dựa trên căn cứ/giác quan quan sát được)', 'ようです là văn viết/lịch sự hơn みたいです, dùng khi có căn cứ quan sát thực tế', 'V(thể thường)／Aい／Aな(な)／N(の) + ようです', 'Phán đoán một sự việc dựa trên căn cứ/giác quan quan sát được', NULL, NULL, NULL, '{}', NULL, 45, 'V（普通形）／Aな（だ）／N（だ）＋ようです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('776ef381-7b4c-47c0-9dad-d23d68287d7c', 'N4', 'V（普通形）／Aい／Aな（だ）／N＋みたいです', 'Hình như, dường như ~ (khẩu ngữ của ようです)', 'みたいです là dạng khẩu ngữ, thân mật hơn của ようです, cùng ý nghĩa phán đoán', 'V(thể thường)／Aい／Aな／N + みたいです', 'Phán đoán một sự việc dựa trên căn cứ quan sát được, dùng trong văn nói thân mật', NULL, NULL, NULL, '{}', NULL, 45, 'V（普通形）／Aい／Aな（だ）／N＋みたいです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0b40238a-6f64-4137-a556-794ef1585f47', 'N4', '音／におい／味＋がします', 'Có tiếng động, mùi, vị...', 'がする gắn sau danh từ chỉ cảm giác giác quan (âm thanh, mùi, vị) mà không cần chủ động tạo ra', '音／におい／味 + が + します', 'Diễn tả việc cảm nhận được âm thanh, mùi, vị một cách tự nhiên (không chủ ý)', NULL, NULL, NULL, '{}', NULL, 45, '音／におい／味＋がします', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('34789259-540e-4bd9-92a3-41b6540acd51', 'N4', 'Vさせていただけませんか。', 'Xin cho tôi được ~ (xin phép rất lịch sự)', 'させていただけませんか là dạng xin phép khiêm nhường, lịch sự nhất trong các cách xin phép', 'V(thể sai khiến て形) + いただけませんか', 'Xin phép ai đó cho mình làm gì một cách rất lịch sự, khiêm nhường', NULL, NULL, NULL, '{}', NULL, 45, 'Vさせていただけませんか。', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('da963a11-d0dd-412b-8a6c-277eeb3802cf', 'N4', 'Vさせていただきます。', 'Tôi xin phép ~ (thông báo lịch sự việc mình sẽ làm)', 'させていただきます dùng để thông báo lịch sự một hành động mình sắp làm, có xin phép trước', 'V(thể sai khiến て形) + いただきます', 'Thông báo một cách lịch sự, khiêm nhường về việc mình sẽ làm (đã được cho phép)', NULL, NULL, NULL, '{}', NULL, 45, 'Vさせていただきます。', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fbe1065e-000b-404e-bbc3-307fe2760bfa', 'N4', 'Vさせる（使役形）', 'Thể sai khiến: bắt/cho phép ai đó làm gì', 'Trợ từ đánh dấu người bị sai khiến khác nhau tùy động từ tha động (に) hay tự động (を)', 'V(thể sai khiến): 五段→ 語幹+せる／一段→ 語幹+させる／する→させる／来る→来させる', NULL, NULL, NULL, NULL, '{}', NULL, 45, 'Vさせる（使役形）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a7d55ba1-df2a-41b4-801c-0c8b93dff3e9', 'N4', '尊敬語（Dạng đặc biệt của động từ）', 'Kính ngữ đặc biệt: します／います／行きます・来ます đổi thành dạng tôn kính riêng', '3 cặp động từ này KHÔNG chia theo quy tắc お＋Vます形＋になります thông thường mà có dạng đặc biệt riêng', 'します → なさいます／います → いらっしゃいます／行きます・来ます → いらっしゃいます', NULL, NULL, NULL, NULL, '{}', NULL, 45, '尊敬語（Dạng đặc biệt của động từ）', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('5abcfd0d-4581-4608-bec6-66a63aa8e3e0', 'fbe1065e-000b-404e-bbc3-307fe2760bfa', 1, 'Người bị sai khiến + に + (tân ngữ)を + V(thể sai khiến) — dùng với động từ tha động (có tân ngữ)', 'N1は N2に N3を V(thể sai khiến)', NULL, NULL, 45, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('e0dc6c9a-7a26-4d99-b679-2b454285ae25', 'fbe1065e-000b-404e-bbc3-307fe2760bfa', 2, 'Người bị sai khiến + を + V(thể sai khiến) — dùng với động từ tự động (không tân ngữ)', 'N1は N2を V(thể sai khiến)', NULL, NULL, 45, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('18dc3aa3-10dc-40a2-baa2-6fbe7a733def', 'a7d55ba1-df2a-41b4-801c-0c8b93dff3e9', 1, 'します → なさいます', 'します → なさいます', NULL, NULL, 45, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('58dff9b2-f2e7-4cc5-a266-61fdc3e419ae', 'a7d55ba1-df2a-41b4-801c-0c8b93dff3e9', 2, 'います → いらっしゃいます', 'います → いらっしゃいます', NULL, NULL, 45, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('1edd12d4-2e66-41c3-a477-d522218e7a6c', 'a7d55ba1-df2a-41b4-801c-0c8b93dff3e9', 3, '行きます／来ます → いらっしゃいます', '行きます／来ます → いらっしゃいます', NULL, NULL, 45, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', NULL, 1, 'daily', '雪が降ってきましたから、寒いはずです。', 'Bởi vì tuyết vừa rơi nên trời chắc chắn sẽ lạnh.', '雪が降ってきましたから、寒い＿＿＿。', 'はずです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', NULL, 2, 'daily', '彼は日本に10年住んでいたから、日本語が上手なはずです。', 'Vì anh ấy đã sống ở Nhật 10 năm nên chắc chắn giỏi tiếng Nhật.', '彼は日本に10年住んでいたから、日本語が上手な＿＿＿。', 'はずです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', NULL, 3, 'daily', 'もう7時ですから、店は閉まっているはずです。', 'Vì đã 7 giờ rồi nên cửa hàng chắc chắn đã đóng cửa.', 'もう7時ですから、店は閉まっている＿＿＿。', 'はずです', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', NULL, 'fill_blank', 'Điền vào chỗ trống: 雪が降ってきましたから、寒い＿＿＿。', NULL, NULL, NULL, NULL, 'はずです', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', NULL, 'choose_meaning', '「彼は日本に10年住んでいたから、日本語が上手なはずです。」nghĩa là gì?', NULL, NULL, NULL, NULL, 'Vì anh ấy đã sống ở Nhật 10 năm nên chắc chắn giỏi tiếng Nhật.', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('6ffab807-1edd-4bd6-bc62-b08e5e862373', NULL, 'choose_pattern', 'Chọn mẫu ngữ pháp đúng cho câu: もう7時ですから、店は閉まっている＿＿＿。', NULL, NULL, NULL, NULL, 'はずです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('754f3c2e-1837-4931-a447-9f553b84ea88', NULL, 1, 'daily', '天気予報によると、明日雨が降るそうです。', 'Theo như dự báo thời tiết, nghe nói ngày mai sẽ mưa.', '天気予報によると、明日雨が＿＿＿。', '降るそうです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('754f3c2e-1837-4931-a447-9f553b84ea88', NULL, 2, 'daily', 'ニュースによると、あの俳優は来月結婚するそうです。', 'Theo tin tức, nghe nói diễn viên đó sẽ kết hôn vào tháng sau.', 'ニュースによると、あの俳優は来月＿＿＿。', '結婚するそうです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('754f3c2e-1837-4931-a447-9f553b84ea88', NULL, 3, 'daily', '田中さんの話では、この店の料理はとてもおいしいそうです。', 'Theo lời anh Tanaka, nghe nói món ăn ở quán này rất ngon.', '田中さんの話では、この店の料理はとても＿＿＿。', 'おいしいそうです', 'generated');
