insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('754f3c2e-1837-4931-a447-9f553b84ea88', NULL, 'choose_meaning', '「ニュースによると、あの俳優は来月結婚するそうです。」nghĩa là gì?', NULL, NULL, NULL, NULL, 'Theo tin tức, nghe nói diễn viên đó sẽ kết hôn vào tháng sau.', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('754f3c2e-1837-4931-a447-9f553b84ea88', NULL, 'choose_pattern', 'Chọn mẫu ngữ pháp đúng cho câu: 田中さんの話では、この店の料理はとても＿＿＿。', NULL, NULL, NULL, NULL, 'おいしいそうです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e3673d1b-72e3-4112-a5de-f601fbb23ecc', NULL, 1, 'daily', '彼はN1を合格したようです。', 'Hình như anh ấy đã thi đỗ N1.', '彼はN1を合格した＿＿＿。', 'ようです', 'pdf');
